import { unstable_cache } from 'next/cache';
import fs from 'fs/promises';
import path from 'path';

const DB_PATH = path.join(process.cwd(), 'posts.json');

// Helper to read posts
async function readPostsFromFile() {
  try {
    const data = await fs.readFile(DB_PATH, 'utf-8');
    return JSON.parse(data);
  } catch (error) {
    // If file doesn't exist, return empty array
    return [];
  }
}

// Helper to write posts
async function writePostsToFile(posts: any[]) {
  await fs.writeFile(DB_PATH, JSON.stringify(posts, null, 2));
}

export const getPosts = unstable_cache(
  async () => {
    return await readPostsFromFile();
  },
  ['posts-list'], // Key parts for cache identification
  {
    tags: ['posts'], // The cache tag to invalidate
  }
);

export async function addPost(post: { title: string; content: string }) {
  const posts = await readPostsFromFile();
  const newPost = { id: Date.now().toString(), ...post, createdAt: new Date().toISOString() };
  posts.push(newPost);
  await writePostsToFile(posts);
  return newPost;
}

'use server';

import { revalidateTag } from 'next/cache';
import { addPost } from './lib/db';
import { redirect } from 'next/navigation';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title || !content) {
    throw new Error('Title and content are required');
  }

  await addPost({ title, content });

  // Invalidate the cache for the 'posts' tag
  revalidateTag('posts');

  // Optionally redirect to force a fresh render if not already on the page, 
  // though revalidateTag handles the data freshness on re-render.
  // The user didn't explicitly ask for redirect, but usually after creating a post, 
  // you might want to stay on the page or go to list.
  // The prompt says "After creating the post, invalidate...". It doesn't mention redirect.
  // But a server action usually returns void or data.
}

import { getPosts } from './lib/db';
import { createPost } from './actions';

export default async function Home() {
  const posts = await getPosts();

  return (
    <main className="p-4">
      <h1 className="text-2xl font-bold mb-4">Posts</h1>

      <div className="mb-8">
        <h2 className="text-xl font-semibold mb-2">Create New Post</h2>
        <form action={createPost} className="space-y-4">
          <div>
            <label htmlFor="title" className="block text-sm font-medium text-gray-700">Title</label>
            <input type="text" name="title" id="title" required className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm border p-2" />
          </div>
          <div>
            <label htmlFor="content" className="block text-sm font-medium text-gray-700">Content</label>
            <textarea name="content" id="content" required rows={3} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm border p-2"></textarea>
          </div>
          <button type="submit" className="inline-flex justify-center rounded-md border border-transparent bg-indigo-600 py-2 px-4 text-sm font-medium text-white shadow-sm hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2">
            Add Post
          </button>
        </form>
      </div>

      <div className="space-y-4">
        {posts.length === 0 ? (
          <p className="text-gray-500">No posts yet.</p>
        ) : (
          posts.map((post: any) => (
            <div key={post.id} className="border rounded-lg p-4 shadow-sm">
              <h3 className="text-lg font-bold">{post.title}</h3>
              <p className="text-gray-700 mt-1">{post.content}</p>
              <p className="text-xs text-gray-400 mt-2">Created at: {new Date(post.createdAt).toLocaleString()}</p>
            </div>
          ))
        )}
      </div>
    </main>
  );
}

